import{c as s,Q as n,j as e,m as p}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"OpAICoreConfig注册接口（REGISTER_OP_AICORE_CONFIG）","description":"","frontmatter":{},"headers":[{"level":1,"title":"OpAICoreConfig注册接口（REGISTER\\\\_OP\\\\_AICORE\\\\_CONFIG）","slug":"opaicoreconfig注册接口register_op_aicore_config"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/原型注册与管理/OpAICoreConfig注册接口（REGISTER_OP_AICORE_CONFIG）.md","filePath":"api/Utils-API/原型注册与管理/OpAICoreConfig注册接口（REGISTER_OP_AICORE_CONFIG）.md"}'),t={name:"api/Utils-API/原型注册与管理/OpAICoreConfig注册接口（REGISTER_OP_AICORE_CONFIG）.md"};function i(o,a,l,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="opaicoreconfig注册接口-register-op-aicore-config" tabindex="-1">OpAICoreConfig注册接口（REGISTER_OP_AICORE_CONFIG） <a class="header-anchor" href="#opaicoreconfig注册接口-register-op-aicore-config" aria-label="Permalink to &quot;OpAICoreConfig注册接口（REGISTER\\_OP\\_AICORE\\_CONFIG）&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>不同的硬件形态算子原型定义不同的情况，可以通过新增<a href="./OpAICoreConfig/OpAICoreConfig.html">OpAICoreConfig</a>的方式，针对不同的AI处理器型号<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/guide/%E7%BC%96%E7%A8%8B%E6%8C%87%E5%8D%97/%E9%AB%98%E7%BA%A7%E7%BC%96%E7%A8%8B/%E9%AB%98%E7%BA%A7%E7%89%B9%E6%80%A7/Aclnn%E7%AE%97%E5%AD%90%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%BC%80%E5%8F%91/%E7%AE%97%E5%AD%90%E5%8E%9F%E5%9E%8B%E5%AE%9A%E4%B9%89.md" target="_blank" rel="noreferrer">注册差异化的算子原型</a>。REGISTER_OP_AICORE_CONFIG宏在不改变原有注册的基础上，允许单独新增文件来注册算子在不同硬件形态上的差异化信息。</p><p>使用该注册宏需要包含以下头文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;register/op_config_registry.h&quot;</span></span></code></pre></div><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGISTER_OP_AICORE_CONFIG(opType, socVersion, opFunc)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>opType</td><td>输入</td><td>算子类型。</td></tr><tr><td>socVersion</td><td>输入</td><td>支持的AI处理器型号。</td></tr><tr><td>opFunc</td><td>输入</td><td>返回OpAICoreConfig的回调函数指针，回调函数原型定义为： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen35771245210&quot;&gt;OpAICoreConfig (*)()&lt;/pre&gt;</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>若算子同时使用<a href="./OpAICoreDef/AddConfig.html">AddConfig</a>注册算子支持的AI处理器型号以及OpAICoreConfig信息，且AI处理器型号相同时，通过AddConfig方式注册的配置优先级更高，会覆盖REGISTER_OP_AICORE_CONFIG宏注册的OpAICoreConfig信息。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>假设，已有原型注册文件op_host/add_custom.cpp实现如下，配置了算子支持的AI处理器型号ascendxxx1及算子输入输出原型信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>...</span></span>
<span class="line"><span>namespace ops {</span></span>
<span class="line"><span>class AddCustom : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    AddCustom(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_INT32})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;AICore()</span></span>
<span class="line"><span>            .SetTiling(optiling::TilingFunc);</span></span>
<span class="line"><span>        // 请替换为实际的AI处理器型号</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx1&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>OP_ADD(AddCustom);</span></span>
<span class="line"><span>} // namespace ops</span></span></code></pre></div><p>可新增文件op_host/add_custom_xxx.cpp，使用REGISTER_OP_AICORE_CONFIG单独注册算子支持的AI处理器型号ascendxxx2，示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;register/op_config_registry.h&quot;</span></span>
<span class="line"><span>namespace ops {</span></span>
<span class="line"><span>REGISTER_OP_AICORE_CONFIG(AddCustom, ascendxxx2, []() {</span></span>
<span class="line"><span>    ops::OpAICoreConfig config(&quot;ascendxxx2&quot;);</span></span>
<span class="line"><span>    return config;</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,18)])])}const h=s(t,[["render",i]]);export{_ as __pageData,h as default};
